SELECT p.pid,t.tid,s.ts,s.dur,s.cpu,s.end_state FROM sched_slice s JOIN thread t USING(utid) JOIN process p USING(upid) WHERE p.pid IN (5900,6577,6974,7656,8109,8729,9347,9849,10636,11199) AND (t.tid IN (5923,5923,6601,6601,6998,6998,7679,7679,8133,8133,8753,8753,9368,9368,9873,9873,10656,10656,11223,11223) OR t.tid=p.pid) AND s.ts < 288812244900 AND s.ts+s.dur > 160198738000 ORDER BY p.pid,t.tid,s.ts;
